python - <<'PY'
import pandas as pd,numpy as np
from pymatgen.core import Structure
po=pd.read_csv('nlo_pool.csv')
for cid in ['c061','c062','c089']:
 s=Structure.from_str(po[po.candidate_id==cid].poscar.iloc[0],fmt='poscar')
 print(cid)
 for i,site in enumerate(s):
  if site.specie.symbol in ['B']:
   n=sorted(s.get_neighbors(site,2.2),key=lambda x:x.nn_distance)
   print(site.frac_coords,[(x.specie.symbol,x.nn_distance,x.frac_coords) for x in n]);
   if len(n)==2:
    v=[x.coords-site.coords for x in n];print('angle',np.degrees(np.arccos(np.dot(v[0],v[1])/np.linalg.norm(v[0])/np.linalg.norm(v[1]))))
